/* cppi::b8a266e5f3cc0671d907fb309047cba3e4f4b2706b560f0f317a09f46366c9d2 */
select business_date as date_, security_id, 'SP500_35' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-20' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'SP500_35_GR_USD_0_0' and security_id is not null

/* cppi::fe7d241af9a6b803eae0511daabb221179d73c9e160461a22500667d529863eb */
